(()=>{"use strict";class LiteSwiper{constructor(selector,options={}){this.root=typeof selector==="string"?document.querySelector(selector):selector;this.options=options;if(!this.root)return;this.track=this.root.querySelector(".swiper-wrapper");this.slides=[...this.root.querySelectorAll(".swiper-slide")];this.pagination=this.root.querySelector(options.pagination?.el||".swiper-pagination");this.timer=null;if(!this.track||!this.slides.length)return;this.renderPagination();this.track.addEventListener("scroll",()=>this.syncPagination(),{passive:true});this.root.addEventListener("pointerdown",()=>this.stop());this.root.addEventListener("focusin",()=>this.stop());if(options.autoplay)this.start()}visibleCount(){return matchMedia("(min-width:768px)").matches?3:matchMedia("(min-width:520px)").matches?2:1}pageCount(){return Math.max(1,this.slides.length-this.visibleCount()+1)}currentIndex(){const left=this.track.scrollLeft;let best=0,dist=Infinity;this.slides.forEach((slide,i)=>{const d=Math.abs(slide.offsetLeft-left);if(d<dist){dist=d;best=i}});return Math.min(best,this.pageCount()-1)}goTo(i){const max=this.pageCount()-1;const index=Math.max(0,Math.min(max,i));const slide=this.slides[index];if(slide)this.track.scrollTo({left:slide.offsetLeft,behavior:"smooth"});this.setActive(index)}renderPagination(){if(!this.pagination)return;this.pagination.textContent="";for(let i=0;i<this.pageCount();i++){const b=document.createElement("button");b.type="button";b.className="swiper-pagination-bullet"+(i===0?" swiper-pagination-bullet-active":"");b.setAttribute("aria-label",`Show testimonial ${i+1}`);b.addEventListener("click",()=>this.goTo(i));this.pagination.appendChild(b)}}setActive(index){if(!this.pagination)return;[...this.pagination.children].forEach((b,i)=>b.classList.toggle("swiper-pagination-bullet-active",i===index))}syncPagination(){this.setActive(this.currentIndex())}start(){const delay=Math.max(1800,Number(this.options.autoplay?.delay||2800));this.timer=setInterval(()=>{const next=(this.currentIndex()+1)%this.pageCount();this.goTo(next)},delay)}stop(){if(this.timer){clearInterval(this.timer);this.timer=null}}}window.Swiper=window.Swiper||LiteSwiper})();
